async function handleJobStatus(input) {
  const wait = Math.max(0, Math.min(60, input.wait_seconds ?? 30));
  const deadline = Date.now() + wait * 1e3;
  let lastProgress = -1;
  try {
    while (true) {
      const res = await fetch(`http://localhost:3847/api/job/${input.job_id}`);
      if (res.status === 404) {
        return JSON.stringify({ error: `Job ${input.job_id} not found` });
      }
      if (!res.ok)
        throw new Error(`HTTP ${res.status}`);
      const job = await res.json();
      const progressChanged = job.progress !== lastProgress;
      const terminal = job.status === "done" || job.status === "error";
      if (terminal || progressChanged || Date.now() >= deadline) {
        return JSON.stringify({
          status: job.status,
          progress: job.progress,
          message: job.message,
          done: terminal,
          error: job.error,
          next_step: job.status === "done" ? "Job complete. For transcription: get_ui_state(include_transcript: true). For renders: clips are on disk \u2014 the result field lists paths." : job.status === "error" ? "Job failed \u2014 check the error. Retry the original start call if appropriate." : `Still running \u2014 call job_status("${input.job_id}", wait_seconds: 30) again and emit one terse progress line to the user between polls.`
        });
      }
      lastProgress = job.progress;
      await new Promise((r) => setTimeout(r, 2e3));
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    if (msg.includes("ECONNREFUSED") || msg.includes("fetch failed")) {
      return JSON.stringify({ error: "Web UI not running." });
    }
    throw err;
  }
}

